#define main archived_langford_main
#include "study_source.cuh"
#undef main
#include <cstdio>
#include <string>
#define CK(x)do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}while(0)
std::vector<int64_t>read_expected(){FILE*f=fopen("expected_i64.bin","rb");if(!f)exit(3);fseek(f,0,SEEK_END);size_t n=ftell(f)/8;rewind(f);std::vector<int64_t>v(n);if(fread(v.data(),8,n,f)!=n)exit(4);fclose(f);return v;}
template<int n>void capture(int64_t*d,std::vector<int64_t>&out){constexpr int pad=(n+7)/8;int64_t cnt;CK(cudaMemcpy(&cnt,d,8,cudaMemcpyDeviceToHost));if(cnt<0||cnt>=4096)exit(5);std::vector<int64_t>raw(cnt*pad);if(cnt)CK(cudaMemcpy(raw.data(),d+1,raw.size()*8,cudaMemcpyDeviceToHost));Results<n>v;for(int i=0;i<cnt;i++){Positions<n>p;auto ptr=(int8_t*)(raw.data()+i*pad);for(int j=0;j<n;j++)p[j]=ptr[j];v.push_back(p);}std::sort(v.begin(),v.end());int64_t uniq=0;for(int i=0;i<cnt;i++)if(i==0||v[i]!=v[i-1])uniq++;out.push_back(n);out.push_back(cnt);out.push_back(uniq);for(auto&p:v)for(auto x:p)out.push_back(x);for(int64_t i=cnt*n;i<4096*n;i++)out.push_back(0);}

int main(){int ns[]={7,8,11,12,15};int64_t*dev[5];for(int j=0;j<5;j++){int pad=(ns[j]+7)/8;CK(cudaMalloc(&dev[j],(1+4096*pad)*8));CK(cudaMemset(dev[j],0,8));}
auto run=[&](int j){switch(j){case 0:dfs_gpu<7><<<4096,4>>>(dev[j]);break;case 1:dfs_gpu<8><<<4096,4>>>(dev[j]);break;case 2:dfs_gpu<11><<<4096,4>>>(dev[j]);break;case 3:dfs_gpu<12><<<4096,4>>>(dev[j]);break;case 4:dfs_gpu<15><<<4096,4>>>(dev[j]);break;}};for(int j=0;j<5;j++)run(j);CK(cudaDeviceSynchronize());auto expected=read_expected();bool all=true;
for(int trial=1;trial<=5;trial++){std::vector<double>ts;for(int j=0;j<5;j++){CK(cudaMemset(dev[j],0,8));CK(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();run(j);CK(cudaGetLastError());CK(cudaDeviceSynchronize());ts.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count());}std::vector<int64_t>out;capture<7>(dev[0],out);capture<8>(dev[1],out);capture<11>(dev[2],out);capture<12>(dev[3],out);capture<15>(dev[4],out);bool ok=out==expected;all&=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/langford_trial"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");if(!f)return 6;fwrite(out.data(),8,out.size(),f);fclose(f);double total=0;for(auto t:ts)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"component_seconds\":[%.12g,%.12g,%.12g,%.12g,%.12g],\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":%d,\"internal_repeats\":1,\"jit_excluded\":true,\"timing_region\":\"sum_five_sourcecase_GPU_DFS_launch_completion\",\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ts[0],ts[1],ts[2],ts[3],ts[4],ok?"true":"false",out.size(),ok?0:1,ok?0:1,path.c_str(),out.size());}for(auto p:dev)CK(cudaFree(p));puts(all?"PASS":"FAIL");return all?0:1;}
